class Group:
    def __init__(self, members: list[str]) -> None:
        # Preserve order of members as passed, while enabling fast membership check
        self._members: list[str] = list(members)
        self._members_set: set[str] = set(self._members)
        # Store balances in cents (int) to prevent floating-point inaccuracies
        self._balances: dict[str, int] = {m: 0 for m in self._members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be strictly positive.")

        if payer not in self._members_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            parts = list(self._members)
        else:
            parts = list(participants)

        if not parts:
            raise ValueError("Participants list cannot be empty.")

        for p in parts:
            if p not in self._members_set:
                raise ValueError(f"Participant '{p}' is not a group member.")

        # Convert total amount to integer cents
        total_cents = round(amount * 100)
        n = len(parts)

        # Each participant owes floor(total_cents / n) cents
        base_split = total_cents // n

        for p in parts:
            if p == payer:
                # If payer is among participants:
                # Payer paid total_cents, but consumes (base_split + leftover_cents).
                # Net gain for payer from this transaction = total_cents - (base_split + remainder)
                # Remainder is total_cents - base_split * n.
                # So net gain = total_cents - (base_split + total_cents - base_split * n)
                #             = base_split * (n - 1)
                # Note: this is exactly the sum of base_split received from all other (n - 1) participants!
                pass
            else:
                self._balances[p] -= base_split
                self._balances[payer] += base_split

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances[m] / 100.0 for m in self._members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Separate debtors (negative balance) and creditors (positive balance)
        debtors: list[list] = []
        creditors: list[list] = []

        for m in self._members:
            bal = self._balances[m]
            if bal < 0:
                debtors.append([m, -bal])
            elif bal > 0:
                creditors.append([m, bal])

        payments: list[tuple[str, str, float]] = []

        i, j = 0, 0
        while i < len(debtors) and j < len(creditors):
            debtor, debt_amount = debtors[i]
            creditor, credit_amount = creditors[j]

            transfer = min(debt_amount, credit_amount)

            # Rule: settle_up() never proposes a payment smaller than 1.00;
            # debts below 1.00 are written off and not included in proposed payments.
            if transfer >= 100:
                payments.append((debtor, creditor, transfer / 100.0))

            debtors[i][1] -= transfer
            creditors[j][1] -= transfer

            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1

        return payments
